using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class AuditTreePieces {public static object Main(){var cs=UnityEngine.Object.FindObjectsByType<Collider>().Where(c=>c.name.ToLower().Contains("tree")||c.name.ToLower().Contains("trunk")).ToArray();var rows=new List<string>();foreach(var mf in UnityEngine.Object.FindObjectsByType<MeshFilter>().Where(m=>m.GetComponent<Renderer>()&&m.GetComponent<Renderer>().sharedMaterial&&m.GetComponent<Renderer>().sharedMaterial.name=="Forest"&&m.GetComponent<Renderer>().bounds.Intersects(new Bounds(new(401,50,-195),new(80,100,55))))){var v=mf.sharedMesh.vertices;var ts=mf.sharedMesh.triangles;var used=ts.Distinct().ToArray();var parents=Enumerable.Range(0,v.Length).ToArray();int F(int i){while(parents[i]!=i){parents[i]=parents[parents[i]];i=parents[i];}return i;}void J(int a,int b){parents[F(a)]=F(b);}var weld=new Dictionary<Vector3Int,int>();foreach(int i in used){var key=Vector3Int.RoundToInt(v[i]*1000);if(weld.TryGetValue(key,out int o))J(i,o);else weld[key]=i;}for(int i=0;i<ts.Length;i+=3){J(ts[i],ts[i+1]);J(ts[i],ts[i+2]);}foreach(var g in used.GroupBy(F)){var b=new Bounds(mf.transform.TransformPoint(v[g.First()]),Vector3.zero);foreach(int i in g)b.Encapsulate(mf.transform.TransformPoint(v[i]));if(b.center.x<355||b.center.x>435||b.center.z<-217||b.center.z>-175)continue;var c=cs.OrderBy(c=>Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(b.center.x,b.center.z))).First();float d=Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(b.center.x,b.center.z));rows.Add(mf.name+" group="+g.Key+" bounds="+b+" nearest="+c.name+" "+c.bounds.center+" distance="+d);}}
File.WriteAllLines("Docs/BackyardReverse/tree-piece-audit.txt",rows);return rows;}}

